using Studio.Core;
using Studio.Raple;

var adapter=new RapleAdapter(Path.GetFullPath(args.FirstOrDefault()??"../raple-realms-7-server"));var checks=0;
void Check(bool value,string label){if(!value)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
void Reject(Action action,string label){try{action();}catch(Exception e)when(e is ArgumentException or InvalidOperationException){Check(true,label);return;}throw new Exception("Expected rejection: "+label);}
const string entity="Cave Pirate Brawler";var file=adapter.Catalog().Single(e=>e.Id==entity).SourceFile;var supplied=File.ReadAllText(file);
const string source="""
using TKR.WorldServer.logic.behaviors;
namespace TKR.WorldServer.logic { public partial class BehaviorDb {
    private _ StudioParamsEntry=()=>Behav().Init("Cave Pirate Brawler",new State("loop",StudioParamsWrap(new StudioParamsChildren(){ {20,new Shoot(20,count:4,fixedAngle:0,coolDown:100),/* params note */new Shoot(20,count:2,fixedAngle:0,coolDown:100)},{11,new CycleBehavior[]{new Shoot(20,count:3,fixedAngle:0,coolDown:100)}},{9} })));
    static Prioritize StudioParamsWrap(System.Collections.Generic.IEnumerable<CycleBehavior> children)=>new Prioritize(System.Linq.Enumerable.ToArray(children));
    sealed class StudioParamsChildren:System.Collections.Generic.IEnumerable<CycleBehavior> {
        readonly System.Collections.Generic.SortedDictionary<int,CycleBehavior[]> values=new();
        public void Add(int key,params CycleBehavior[] children)=>values.Add(key,System.Linq.Enumerable.ToArray(System.Linq.Enumerable.Reverse(children)));
        public System.Collections.Generic.IEnumerator<CycleBehavior> GetEnumerator()=>System.Linq.Enumerable.SelectMany(values.Values,v=>v).GetEnumerator();
        System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator()=>GetEnumerator();
    }
} }
""";
var doc=new BehaviorDocument(source,adapter,sourceFile:file);var list=doc.Entities.Single().Root.Descendants().Single(n=>n.Kind=="ArgumentGroup"&&n.Children.Any(c=>c.Kind=="InitializerEntry"));var first=list.Children[0];var second=list.Children[1];var empty=list.Children[2];var expanded=first.Children.Single();var explicitArray=second.Children.Single();var emptySlot=empty.Children.Single();var ids=doc.Identities;
Check(expanded.Argument is{IsParams:true,IsArray:true}&&expanded.ArgumentFromCall&&!expanded.ArgumentRequiresSource&&expanded.Children.Count==2,"Compiler-selected expanded Add arguments expose one typed params list");
Check(!explicitArray.ArgumentFromCall&&explicitArray.Children.Single().Kind=="Shoot"&&explicitArray.Argument?.IsParams==true,"An explicit params array retains its own native source list");Check(emptySlot.Children.Count==0&&doc.CanEditChildren(emptySlot.Id),"An omitted params Add input exposes an editable empty list");
Check(doc.AcceptsChild(expanded.Id,"new Shoot(20)")&&!doc.AcceptsChild(expanded.Id,"new global::TKR.WorldServer.logic.transitions.TimedTransition(100,\"loop\")"),"Expanded params preserve exact native element conversion");
doc.MoveNode(expanded.Children[1].Id,-1,d=>adapter.Validate(d,entity));Check(doc.Find(expanded.Id).Children.First().Id==expanded.Children[1].Id&&!doc.Expression(doc.Find(first.Id)).Contains("new CycleBehavior[]")&&doc.Source.Contains("/* params note */"),"Expanded reorder retains argument form, scalar key, comments and identities");
var duplicate=doc.DuplicateNode(expanded.Children[0].Id,d=>adapter.Validate(d,entity));Check(doc.Find(expanded.Id).Children.Count==3&&duplicate!=expanded.Children[0].Id,"Native params child duplication creates a fresh descendant without copying its entry");doc.Undo();
doc.DeleteNodes(doc.Find(expanded.Id).Children.Select(n=>n.Id),d=>adapter.Validate(d,entity));Check(doc.Find(expanded.Id).Children.Count==0&&doc.Expression(doc.Find(first.Id))=="{20}","Removing every expanded argument preserves the actual empty params call");
doc.AddChild(expanded.Id,"new Shoot(20,count:6,fixedAngle:0,coolDown:100)",d=>adapter.Validate(d,entity));Check(doc.Find(expanded.Id).Children.Single().Kind=="Shoot"&&doc.Expression(doc.Find(first.Id)).Contains("CycleBehavior[]"),"Refilling an empty params call creates an explicit native array without shifting the key");
doc.AddChild(emptySlot.Id,"new Shoot(20,count:5,fixedAngle:0,coolDown:100)",d=>adapter.Validate(d,entity));Check(doc.Find(emptySlot.Id).Children.Count==1,"Originally omitted params slots support native refill");
doc.MoveNodes([doc.Find(expanded.Id).Children.Single().Id],explicitArray.Id,1,d=>adapter.Validate(d,entity));Check(doc.Find(expanded.Id).Children.Count==0&&doc.Find(explicitArray.Id).Children.Count==2,"Moves between entry-owned params inputs preserve native list ownership");doc.Undo();
doc.LockedNodes.Add(second.Id);doc.AddChild(expanded.Id,"new Shoot(20,count:8,fixedAngle:0,coolDown:100)",d=>adapter.Validate(d,entity));Check(doc.Find(second.Id).Children.Single().Children.Single().Id==explicitArray.Children.Single().Id,"An unrelated locked entry permits params input editing");doc.LockedNodes.Clear();doc.LockedNodes.Add(expanded.Id);Reject(()=>doc.AddChild(expanded.Id,"new Shoot(20)"),"A params slot lock protects native descendants");doc.LockedNodes.Clear();
var accepted=doc.Source;Reject(()=>doc.AddChild(expanded.Id,"new global::TKR.WorldServer.logic.transitions.TimedTransition(100,\"loop\")"),"Incompatible params insertion rejects atomically");Check(doc.Source==accepted,"Rejected params edits preserve accepted source");
var output=Path.GetFullPath(".artifacts/params-entry");Directory.CreateDirectory(output);var project=new StudioProject{SourceFile=file,Source=doc.Source,EntityId=entity,Identities=doc.Identities,Player=new(Invulnerable:true),Seed=7};var path=Path.Combine(output,"params.rbs");BehaviorDocument.Save(path,project);var saved=BehaviorDocument.Load(path);Check(new BehaviorDocument(saved.Source,adapter,saved.Identities,file).Identities.SequenceEqual(doc.Identities),"Params entry, slot and element identities persist through save/reopen");
await using(var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,project)){await native.AdvanceAsync(new(),100);Check(native.Shots.Select(s=>s.Count).SequenceEqual(new[]{5,3,8,6}),"Actual params Add reversal and sorted enumeration execute every edited native input");}
while(doc.Source!=source)if(!doc.Undo())throw new Exception("Could not restore params history");Check(doc.Identities.SequenceEqual(ids),"Complete params history restores original expanded/explicit/omitted forms and identities");
var revision=doc.Revision;var created=doc.CreateInitializerEntry(first.Id,new Dictionary<string,string>{{"key","7"}},new Dictionary<string,string>{{"children","[new Shoot(20,count:5,fixedAngle:0,coolDown:100),new Shoot(20,count:9,fixedAngle:0,coolDown:100)]"}},d=>adapter.Validate(d,entity));Check(doc.Revision==revision+1&&doc.Find(created).Children.Single().Children.Count==2&&!doc.Find(created).Children.Single().ArgumentFromCall,"New params entry creation replaces the complete expanded tail with one explicit list in one revision");
var createdSource=doc.Source;var createdIds=doc.Identities;Check(doc.Undo()&&doc.Source==source&&doc.Redo()&&doc.Source==createdSource&&doc.Identities.SequenceEqual(createdIds),"One params creation Undo/Redo retains every fresh descendant");
var blank=doc.CreateInitializerEntry(first.Id,new Dictionary<string,string>{{"key","8"}},new Dictionary<string,string>(),d=>adapter.Validate(d,entity));Check(doc.Find(blank).Children.Single().Children.Count==0&&doc.Expression(doc.Find(blank)).Contains("CycleBehavior[]"),"Blank params creation uses an empty native array rather than copied prototype arguments");doc.Undo();
var pasted=doc.PasteNodes(list.Id,1,doc.CopyNodes([first.Id]),d=>adapter.Validate(d,entity)).Single();Check(doc.Find(pasted).Children.Single().Children.Count==2&&doc.Find(pasted).Descendants().All(n=>!first.Descendants().Select(o=>o.Id).Contains(n.Id)),"Clipboard imports expanded params entries with independent descendant identities");doc.Undo();
Reject(()=>doc.CreateInitializerEntry(first.Id,new Dictionary<string,string>{{"key","8"}},new Dictionary<string,string>{{"children","[new global::TKR.WorldServer.logic.transitions.TimedTransition(100,\"loop\")]"}}),"Invalid complete params creation preserves the accepted transaction");Check(doc.Source==createdSource,"Failed params creation retains accepted source and history");
await using(var native=await CompiledRuntime.StartAsync(adapter.ServerRoot,project with{Source=doc.Source,Identities=doc.Identities})){await native.AdvanceAsync(new(),100);Check(native.Shots.Select(s=>s.Count).SequenceEqual(new[]{9,5,3,2,4}),"Native playback invokes the actual params overload for new and original expanded entries");}
Check(File.ReadAllText(file)==supplied,"Params authoring and native playback preserve supplied game source");Console.WriteLine($"{checks} native params-entry checks passed.");
